"메모리·IDM": "Memory · IDM",
"설계부터 제조, 후공정까지 한 회사가 해요. 이 유형에서만 ①→②→③ 줄무늬가 움직여요. 장비·소재 구역만 외부 회사의 영역이에요.": "One company does everything from design to manufacturing to back-end. Only this type makes the ①→②→③ stripes move. Only the equipment & materials zone belongs to outside companies.",
