"삼성전자 DS·SK하이닉스 신입 직무기술서와 장비·소재사 공고의 지원 전공을 참고해 정리했어요. 같은 직무도 회사와 해마다 달라질 수 있으니 실제 공고를 꼭 확인해 보세요.": "Compiled from entry-level job descriptions at Samsung Electronics DS and SK hynix, plus the majors listed in equipment and materials companies' postings. The same job can vary by company and year, so always check the actual posting.",
