"회사마다 직무 이름과 업무 범위는 다를 수 있어요. 여기 적힌 내용은 여러 곳에서 공통으로 쓰이는 일반적인 설명이에요.{0}": "Job titles and scope differ from company to company. What's written here is a general description common to many places.{0}",
