"시험을 중단할까요? 지금까지의 답안은 채점되지 않아요.": "Stop the exam? Your answers so far won't be graded.",
"풀던 면접으로 돌아가기": "Back to the interview you were on",
"결과로 돌아가기": "Back to results",
"시험으로 돌아가기": "Back to the exam",
