"로그인 모듈을 아직 불러오는 중이에요. 잠시 뒤 다시 눌러 주세요.": "The sign-in module is still loading. Please tap again in a moment.",
"계정에 저장된 학습 기록을 모두 삭제할까요? 이 기기에 있는 기록은 그대로 남지만, 다른 기기와의 동기화는 끊겨요. 삭제한 기록은 되돌릴 수 없어요.": "Delete all study records saved to your account? Records on this device will stay, but syncing with other devices will stop. Deleted records can't be recovered.",
