"구글로 로그인": "Sign in with Google",
"로그인하지 않아도 모든 기능을 그대로 쓸 수 있어요. 구글 이름·이메일·프로필 사진과 학습 기록만 저장해요.": "Every feature works without signing in. Only your Google name, email, profile photo and study records are saved.",
