"⏸ 멈춤": "⏸ Pause",
"반도체 제조 공정 한눈에 보기": "Chipmaking processes at a glance",
"입문 이론 보기 →": "Read the intro theory →",
"🏭 3D 팹 둘러보기": "🏭 Tour the 3D fab",
"문제 풀어 보기": "Try some questions",
"3D 화면을 불러오지 못했어요. 인터넷 연결을 확인하고 다시 열어 주세요.": "Couldn't load the 3D view. Check your internet connection and open it again.",
"박막 증착 장비(CVD)를 직접 조작해 보세요. 방식·온도·압력·RF·시간을 정하고, 웨이퍼를 데우고 가스를 흘려 막을 쌓은 뒤 두께와 단면을 확인해요. 수치는 원리를 이해하기 위해 단순화한 값이에요.": "Run a thin-film deposition tool (CVD) yourself. Set the method, temperature, pressure, RF and time, heat the wafer, flow the gas to build up a film, then check its thickness and cross-section. Numbers are simplified to help you grasp the principles.",
"이온 주입기를 직접 조작해 보세요. 불순물 종류·에너지·도즈·기울기·어닐 온도를 정하고, 이온을 만들어 가속해 웨이퍼에 박은 뒤 어닐링해서 접합 깊이와 면저항을 확인해요. 수치는 원리를 이해하기 위해 단순화한 값이에요.": "Run an ion implanter yourself. Set the dopant, energy, dose, tilt and anneal temperature, make and accelerate ions into the wafer, anneal it, then check the junction depth and sheet resistance. Numbers are simplified to help you grasp the principles.",
"CMP 장비를 직접 조작해 보세요. 슬러리·패드·압력·속도·시간을 정하고 웨이퍼를 패드에 눌러 구리를 간 뒤, 남은 구리·디싱·침식·단차를 확인해요. 수치는 원리를 이해하기 위해 단순화한 값이에요.": "Run a CMP tool yourself. Set the slurry, pad, pressure, speed and time, press the wafer onto the pad to polish the copper, then check remaining copper, dishing, erosion and step height. Numbers are simplified to help you grasp the principles.",
"노광 장비(스캐너)를 직접 조작해 보세요. 광원·렌즈·노광량·초점·정렬을 정하고, 웨이퍼를 정렬하고 찍고 현상해서 선폭과 정렬 오차를 확인해요. 수치는 원리를 이해하기 위해 단순화한 값이에요.": "Run a lithography tool (scanner) yourself. Set the light source, lens, dose, focus and alignment, then align, expose and develop the wafer and check the line width and overlay error. Numbers are simplified to help you grasp the principles.",
"체험 화면을 불러오지 못했어요. 인터넷 연결을 확인하고 다시 열어 주세요.": "Couldn't load the lab. Check your internet connection and open it again.",
