"증착이 끝났어요. 막이": "Deposition done. About",
"nm쯤 쌓였어요(웨이퍼 색이 두께에 따라 바뀌어요). 이제 남은 가스를 빼고 꺼내요.": "nm of film has built up (the wafer's color changes with thickness). Now let's pump out the leftover gas and unload.",
"웨이퍼를 꺼내 이송 챔버로 옮겼어요. 이제 두께와 단면을 재요.": "The wafer is out and in the transfer chamber. Now let's measure thickness and cross-section.",
