". 알루미늄은 녹는점이 660 °C로 낮고 450 °C 근처부터 변형되거나 돌기(힐록)가 생겨서, 배선을 만든 뒤 공정은 400 °C 아래에서 해요(열 예산).{0}": ". Aluminum has a low melting point of 660 °C and starts deforming or growing bumps (hillocks) around 450 °C, so processes after wiring are kept below 400 °C (the thermal budget).{0}",
"ALD는 한 사이클에 약 {0} nm만 쌓여서 100 nm를 채우려면 약 {1}사이클, {2}분이 걸려요. 그래서 실제로는": "ALD builds only about {0} nm per cycle, so filling 100 nm takes about {1} cycles, {2} minutes. That's why in practice it's used for",
