"접합 깊이 {0} nm": "Junction depth {0} nm",
"{0} nm로 너무 깊어요": "{0} nm — too deep",
". {0}에너지를 낮추면(깊이 ∝ 에너지) 얕아져요. 지금 평균 깊이는 {1} nm예요. 짧은 채널에서는 접합이 깊으면 단채널 효과가 심해져서 얕게 만들어야 해요.": ". {0}Lowering the energy (depth ∝ energy) makes it shallower. The current mean depth is {1} nm. In short channels, deep junctions worsen short-channel effects, so they need to be shallow.",
"{0} nm로 너무 얕아요": "{0} nm — too shallow",
"어닐이 {0} °C라": "The anneal is {0} °C, so",
"(활성화 {0}%). 박혀 있기만 해서는 전기가 통하지 않아요. 어닐 온도를 높여 보세요.": "(activation {0}%). Just being lodged there doesn't conduct. Raise the anneal temperature.",
"면저항이 {0} Ω/□라": "Sheet resistance is {0} Ω/□, so",
". 넣은 불순물이 모자라니 도즈를 올려 보세요. 단, 활성 농도는 고용 한계({0} 개/cm³)를 못 넘어요.": ". There aren't enough dopants, so raise the dose. Note that the active concentration can't exceed the solubility limit ({0} /cm³).",
"결정 결함이 남았어요(지수 {0}). 도즈 {1}에 {2}은(는) 결정을 크게 부수고({3}), 어닐 {4} °C로는 다 고치지 못했어요.": "Crystal defects remain (index {0}). At a dose of {1}, {2} smashed the crystal badly ({3}), and an anneal at {4} °C couldn't fix it all.",
"웨이퍼를 {0}°만 기울여서": "The wafer was tilted only {0}°, so",
"이 생겼어요(이온의 {0}%가 결정의 빈 길로 깊이 빠짐). 그래서 농도 곡선 끝에 긴 꼬리가 생겨 접합이 깊어져요. 보통": "occurred ({0}% of the ions slipped deep down the crystal's open lanes). That puts a long tail at the end of the concentration curve and deepens the junction. Usually it's tilted",
"도즈 {0}를 넣는 데": "Implanting a dose of {0} takes",
"{0}초": "{0} s",
"가 걸려 생산량이 시간당 {0}장이에요. 빔 전류는 한계가 있어서(에너지가 낮으면 더 작아요) 도즈가 클수록 오래 걸려요. 도즈를 줄이거나 에너지를 올려 보세요.": ", so throughput is {0} wafers per hour. Beam current is limited (and smaller at low energy), so the bigger the dose, the longer it takes. Lower the dose or raise the energy.",
"{0} · {1} keV · {2} · {3}° · 어닐 {4} °C": "{0} · {1} keV · {2} · {3}° · anneal {4} °C",
"· {0} keV · {1} · {2}° · 어닐 {3} °C": "· {0} keV · {1} · {2}° · anneal {3} °C",
"남음 {0} nm": "{0} nm left",
"{0} (1 이하)": "{0} (≤ 1)",
"패드가 {0} rpm으로 돌고, 슬러리가 뿌려져요. 이제 헤드를 내려 눌러요. (여기부터는 레시피를 바꿀 수 없어요)": "The pad is spinning at {0} rpm and slurry is being dispensed. Now lower the head and press. (From here, the recipe can't be changed.)",
"웨이퍼를 {0} psi로 누르고 있어요. 이제 연마를 시작해요.": "Pressing the wafer at {0} psi. Now start polishing.",
"연마를 {0}초 했어요. {1} 웨이퍼를 씻어서 꺼내요.": "Polished for {0} s. {1} Rinse and unload the wafer.",
"디싱 {0} nm": "Dishing {0} nm",
"침식 {0} nm": "Erosion {0} nm",
"{0}~{1} 초": "{0}–{1} s",
"~{0} 초": "–{0} s",
"(제거 속도 {0} nm/분). 구리가 걷히려면 {1}초가 걸려서 시간 안에 못 끝내요. 구리를 갈 때는": "(removal rate {0} nm/min). Clearing the copper would take {1} s, so it can't finish in time. For polishing copper, use",
"{0} nm 남았어요": "{0} nm of copper left",
"(가장자리가 중앙보다 5% 느리게 깎여서 마지막에 걷혀요). 구리가 다 걷히려면 약 {0}초가 필요해요. 시간을 늘리거나 압력·속도를 올려요. 남은 구리는 배선끼리 이어 붙여 단락을 일으켜요.": "(the edge polishes 5% slower than the center, so it clears last). Clearing all the copper takes about {0} s. Add time or raise the pressure or speed. Leftover copper bridges wires together and causes shorts.",
"단차가 {0} nm": "a step of {0} nm",
"나 남았어요. 평탄화는 깎인 두께에 따라 일어나는데, {0} 단단한 패드와 알맞은 압력이 좋아요.": "remains. Planarization depends on how much is removed, and {0} A hard pad and moderate pressure work best.",
"{0} nm 파였어요(디싱)": "{0} nm scooped out (dishing)",
". 구리가 다 걷힌 뒤에도 {0}초 더 갈았고(과연마), {1}연마 시간을 줄이거나 단단한 패드로 바꿔 보세요. 디싱은 배선 저항을 높여요.": ". Even after the copper cleared, it kept polishing for {0} s more (over-polish). {1}Shorten the polish time or switch to a hard pad. Dishing raises wire resistance.",
"산화막이 {0} nm 깎였어요(침식)": "the oxide was {0} nm worn away (erosion)",
". {0}구리용 슬러리로 바꾸고 과연마를 줄여요.": ". {0}Switch to copper slurry and reduce over-polish.",
"스크래치 위험이 높아요({0})": "scratch risk is high ({0})",
"연마 {0}초 + 로딩·세정으로 생산량이 시간당": "Polishing {0} s plus loading and cleaning, so throughput is",
"{0}장": "{0} wafers",
"{0}·{1} · {2} psi · {3} rpm · {4}초": "{0} · {1} · {2} psi · {3} rpm · {4} s",
"·{0} · {1} psi · {2} rpm · {3}초": "· {0} · {1} psi · {2} rpm · {3} s",
". 구리가 다 걷힌 뒤에도 {0}초 더 갈았고(과연마),": ". Even after the copper cleared, it kept polishing for {0} s more (over-polish),",
