"헹굼": "Rinse",
"어떻게 말릴까요?": "How will you dry them?",
"DHF {0}초": "DHF {0} s",
"헹굼 {0}분": "Rinse {0} min",
"입자 제거": "Particle removal",
"깎임": "Etch loss",
"얼룩": "Stains",
"웨이퍼의 입자·유기물·금속을 지워라: 표면은 거의 깎지 말고, 얼룩 없이, 빠르게": "Wipe out the wafer's particles, organics and metals — barely etch the surface, leave no stains, and do it fast",
"식각 뒤 지저분해진 웨이퍼를 씻어요. 입자와 유기물을 {0}% 이상 지우고, 금속 오염을 {1} atoms/cm² 이하로 줄이고, 실리콘 표면이 {2} nm 넘게 깎이지 않고, 물얼룩·약액 잔류 없이, 시간당 {3}장 이상 씻으면 성공이에요.": "Clean a wafer left dirty after etching. You succeed if you remove at least {0}% of particles and organics, cut metal contamination to {1} atoms/cm² or less, etch the silicon surface by no more than {2} nm, leave no water spots or chemical residue, and clean at least {3} wafers per hour.",
