"약액 온도(℃) ↕ · 나머지는 지금 레시피 그대로": "Chemical temperature (℃) ↕ · everything else as in your current recipe",
"입자 제거(%)": "Particles removed (%)",
"유기물 제거(%)": "Organics removed (%)",
"금속(log10)": "Metal (log10)",
"표면 깎임(nm)": "Surface etch loss (nm)",
"얼룩 위험": "Stain risk",
"생산량(장/h)": "Throughput (wph)",
"칸이 초록이면 그 기준을 만족해요. 한 줄이 전부 초록이면 그 온도가 공정 창이에요. 순서·시간·헹굼·건조를 바꾸면 창이 움직여요. 금속 칸은 오염량의 상용로그(10을 몇 번 곱한 값)예요.": "A green cell meets that criterion. A row that is entirely green is the process window at that temperature. Changing the sequence, time, rinse or drying moves the window. The metal column is the common logarithm of the contamination (how many times 10 is multiplied).",
"세정 이론 보기": "Read cleaning theory",
"입자가 {0}% 남았어요.": "{0}% of the particles are left.",
"입자는 SC-1 약액이 표면을 살짝 깎으며 떼어 내요.": "SC-1 lifts particles off by etching the surface slightly.",
"약액 온도를 높이거나 담그는 시간을 늘려 보세요.": "Raise the chemical temperature or lengthen the dip.",
"스핀 건조는 입자가 조금 더 붙어요.": "Spin drying lets a few more particles stick.",
"유기물이 {0}% 남았어요.": "{0}% of the organics are left.",
"담그는 시간을 늘려 보세요.": "Try a longer dip.",
"두껍게 남은 유기물은 SPM을 앞에 넣으면 훨씬 빨리 지워져요.": "Thick leftover organics come off much faster if you put SPM first.",
"금속 오염이 {0} atoms/cm²로 남았어요.": "Metal contamination remains at {0} atoms/cm².",
"DHF 시간이 짧으면 자연 산화막이 덜 벗겨져 금속이 남아요.": "If the DHF time is short, the native oxide isn't fully stripped and metals stay.",
"SC-2 담금 시간을 늘리는 것도 방법이에요.": "Lengthening the SC-2 dip also helps.",
"SC-1만으로는 금속이 안 지워져요.": "SC-1 alone can't remove metals.",
"오히려 약액에서 금속이 조금 묻어요.": "In fact, a little metal even comes from the chemical.",
"DHF와 SC-2가 들어간 순서로 바꿔 보세요.": "Switch to a sequence that includes DHF and SC-2.",
"실리콘 표면이 {0} nm 깎였어요.": "The silicon surface was etched by {0} nm.",
"SC-1을 뜨겁게 오래 하거나 DHF를 오래 하면 많이 깎여요.": "A long, hot SC-1 or a long DHF etches a lot.",
"온도나 시간을 줄여 보세요.": "Lower the temperature or shorten the time.",
"얼룩·잔류 위험이 {0}예요.": "The stain / residue risk is {0}.",
"헹굼이 모자라면 약액이 남아 얼룩이 생겨요.": "If rinsing is short, chemicals remain and cause stains.",
"헹굼을 늘리거나 IPA 증기 건조로 바꿔 보세요.": "Rinse longer or switch to IPA vapor drying.",
"헹굼 시간을 늘려 보세요.": "Rinse longer.",
"담금·헹굼 시간을 줄이거나 단계를 줄여야 해요.": "Shorten the dip and rinse times, or cut a step.",
"IPA 증기 건조는 시간이 오래 걸려요.": "IPA vapor drying takes a long time.",
"약액을 더 뜨겁게 해서 담금 시간을 줄여 보세요.": "Heat the chemicals more so you can shorten the dip.",
