"뽑은 웨이퍼 {0}장이 이상이었는데 경보가 안 울렸어요.": "{0} sampled wafer(s) were abnormal, but no alarm went off.",
"웨이퍼는 뽑혀도 가장자리 선폭을 어림하는 오차가 커서 경보를 놓쳐요.": "The wafer was sampled, but the error in estimating the edge line width is so large that the alarm is missed.",
