"수직 측벽 · 평평한 윗면 · 충분한 높이": "Vertical sidewall · flat top · sufficient height",
"쉴드·킷": "Shield · kit",
"스로틀 밸브": "Throttle valve",
"스캐너": "Scanner",
"스캐너 · 평행화": "Scanner · parallelizer",
"스캐너는 단독으로 쓰이지 않고, 감광막을 바르고 현상하는 트랙과 옆에 붙어 하나의 클러스터(리소 셀)를 이룬다. 웨이퍼는 FOUP에서 나와 트랙에서 코팅과 베이크를 거쳐 인터페이스를 지나 스캐너에 들어가고, 노광이 끝나면 같은 길로 트랙에 돌아와 노광 후 베이크(PEB)와 현상을 거쳐 FOUP로 나간다. 웨이퍼가 클러스터를 떠나지 않으므로 대기에 노출되지 않고 대기 시간도 일정하게 관리된다.": "The scanner is not used alone; it sits next to the track that coats and develops photoresist and forms one cluster (litho cell). The wafer leaves the FOUP, is coated and baked in the track, passes the interface and enters the scanner. After exposure it returns to the track the same way, goes through post-exposure bake (PEB) and development, and leaves for the FOUP. The wafer never leaves the cluster, so it is not exposed to the atmosphere and the waiting time is held constant.",
"스캔 (한 샷)": "Scan (one shot)",
"스캔 중 물막": "Water film during scan",
"스크래치 · 잔류물 · 부식": "Scratches · residue · corrosion",
"스크린 산화막": "Screen oxide",
"스테이지 A는 렌즈 아래에서 웨이퍼 W1을 노광하고, 그동안 스테이지 B는 왼쪽 측정 위치에서 다음 웨이퍼 W2의 정렬 마크 위치와 표면 높이 지도를 만든다. 측정에 걸리는 시간이 노광 시간 뒤에 숨는다.": "Stage A exposes wafer W1 under the lens, while stage B at the left measurement position builds the alignment mark positions and surface height map of the next wafer W2. The time spent measuring is hidden behind the exposure time.",
"스텝 앤 스캔: 웨이퍼 한 장을 찍는 방법": "Step and scan: how one wafer is printed",
"스트레스": "Stress",
"스팟 빔 스캔 + 웨이퍼 이동": "Spot beam scan + wafer motion",
"스퍼터링: 이온이 때려 원자를 떼어 낸다": "Sputtering: ions knock atoms off",
"슬러리 구성": "Slurry composition",
"슬러리 입자가 골에 고인다": "Slurry particles pool in the valleys",
"슬러리 탱크": "Slurry tank",
"슬러리 한 방울 (확대)": "One drop of slurry (enlarged)",
"슬러리: 구성 성분과 연마 메커니즘": "Slurry: components and polishing mechanism",
"슬러리는 물에 연마 입자(실리카·세리아·알루미나 등)와 여러 약품을 녹이고 섞은 액체다. 산화제는 금속 표면에 무르고 얇은 막을 만들고, 착화제는 그 막을 녹기 쉽게 만들며, 부식 억제제는 파인 곳의 금속이 녹는 것을 막는다. pH 조절제와 계면활성제는 입자가 뭉치지 않고 퍼져 있게 한다.": "Slurry is a liquid in which abrasive particles (silica, ceria, alumina and so on) and several chemicals are mixed into water. The oxidizer makes a soft thin film on the metal surface, the complexing agent makes that film easy to dissolve, and the corrosion inhibitor keeps metal in recessed spots from dissolving. The pH adjuster and surfactant keep the particles dispersed instead of clumping.",
"슬릿": "Slit",
"슬릿 밸브": "Slit valve",
"슬릿 빛은 고정": "Slit light is fixed",
"시간으로만 멈추면 패드가 닳을수록 속도가 달라져 과연마나 미연마가 생긴다. 그래서 연마 중에 신호를 읽어 막이 바뀌는 순간을 찾는다. 대표적인 신호는 모터 전류(마찰의 변화)와 광학 반사율(표면 빛깔의 변화)이다.": "If you stop by time alone, the rate changes as the pad wears, causing over-polish or under-polish. So the signal is read during polishing to find the moment the film changes. Typical signals are motor current (change in friction) and optical reflectance (change in surface color).",
"시스": "Sheath",
"시스와 이온": "Sheath and ions",
"시즈닝": "Seasoning",
"시즈닝: 얇게 덮는다": "Seasoning: cover with a thin film",
"식각 PM1": "Etch PM1",
"식각 PM3": "Etch PM3",
"식각 가스": "Etch gas",
"식각 장비도 가운데 이송 챔버를 로봇이 돌며 주변 챔버로 웨이퍼를 옮기는 클러스터형이다. 식각 챔버 여러 개가 같은 일을 나눠 맡아 처리량을 올리고, 식각이 끝난 웨이퍼는 애싱(감광막 제거) 챔버를 거쳐 나온다.": "The etch tool is also a cluster type, where a robot circles a central transfer chamber and moves wafers to the surrounding chambers. Several etch chambers share the same job to raise throughput, and etched wafers leave through an ashing (photoresist removal) chamber.",
"식각 정지 ·": "Etch stop ·",
