"존 압력 · 링 압력으로 반지름 방향 속도를 맞춘다": "Match the radial rate with zone pressure · ring pressure",
"좁은 홈": "Narrow trench",
"종점": "Endpoint",
"종점 감지": "Endpoint detection",
"종점 감지: 언제 연마를 멈추는가": "Endpoint detection: when to stop polishing",
"종점 검출 (OES)": "Endpoint detection (OES)",
"종점 센서": "Endpoint sensor",
"종횡비 의존 식각 (ARDE)": "Aspect-ratio-dependent etching (ARDE)",
"주입 직후": "Right after implant",
"주입이 남기는 손상과 어닐링": "Damage left by implantation and annealing",
"줄무늬(상)": "Fringes (image)",
"중간 초점": "Intermediate focus",
"중간 홈": "Medium trench",
